import type { RouteStep, Shelf, ShelfLevel } from "../types";
import { metersBetween, type Graph } from "./astar";

// Directions are built from fixed templates and graph geometry only — never generated by an LLM.
// Left/right is only stated when it can be derived: after the shopper has walked one leg (so their heading
// is known), or at the very start when the localized node has a stored facing direction.

type Vec = { x: number; y: number };

function vec(g: Graph, a: string, b: string): Vec {
  const na = g.nodes.get(a)!;
  const nb = g.nodes.get(b)!;
  return { x: (nb.x - na.x) * g.widthM, y: (nb.y - na.y) * g.heightM };
}

/** Signed angle in degrees from heading `a` to heading `b`. Positive = clockwise on the plan = a right turn (y points down). */
function signedAngle(a: Vec, b: Vec): number {
  const cross = a.x * b.y - a.y * b.x;
  const dot = a.x * b.x + a.y * b.y;
  return (Math.atan2(cross, dot) * 180) / Math.PI;
}

export type Turn = "straight" | "slight_left" | "slight_right" | "left" | "right" | "around";

export function classifyTurn(angleDeg: number): Turn {
  const a = Math.abs(angleDeg);
  if (a < 25) return "straight";
  if (a > 155) return "around";
  const side = angleDeg > 0 ? "right" : "left";
  return a < 60 ? (`slight_${side}` as Turn) : side;
}

const TURN_PHRASE: Record<Turn, string> = {
  straight: "Continue straight",
  slight_left: "Bear slightly left",
  slight_right: "Bear slightly right",
  left: "Turn left",
  right: "Turn right",
  around: "Turn around",
};

function headingFromFacing(deg: number): Vec {
  const r = (deg * Math.PI) / 180;
  return { x: Math.sin(r), y: -Math.cos(r) }; // 0° = up on the plan
}

function aboutMeters(m: number): string {
  const r = Math.max(1, Math.round(m));
  return `about ${r} meter${r === 1 ? "" : "s"}`;
}

/** Collapse a node path into legs, merging consecutive segments that continue in roughly the same direction. */
export function toLegs(g: Graph, path: string[]): { from: string; to: string; via: string[] }[] {
  const legs: { from: string; to: string; via: string[] }[] = [];
  for (let i = 0; i < path.length - 1; i++) {
    const a = path[i];
    const b = path[i + 1];
    const last = legs[legs.length - 1];
    if (last && classifyTurn(signedAngle(vec(g, last.via.at(-2) ?? last.from, last.to), vec(g, a, b))) === "straight") {
      last.to = b;
      last.via.push(b);
    } else {
      legs.push({ from: a, to: b, via: [a, b] });
    }
  }
  return legs;
}

function legDistance(g: Graph, via: string[]): number {
  let d = 0;
  for (let i = 0; i < via.length - 1; i++) d += metersBetween(g, via[i], via[i + 1]);
  return d;
}

export interface ArrivalInfo {
  productName: string;
  level: ShelfLevel | null;
}

/** Which side of the shopper the shelf is on, given the direction they arrived from. */
export function shelfSide(g: Graph, arrivingFrom: string | null, anchor: string, shelf: Shelf): "left" | "right" | null {
  if (!arrivingFrom) return null;
  const heading = vec(g, arrivingFrom, anchor);
  const a = g.nodes.get(anchor)!;
  const toShelf = { x: (shelf.x + shelf.w / 2 - a.x) * g.widthM, y: (shelf.y + shelf.h / 2 - a.y) * g.heightM };
  const cross = heading.x * toShelf.y - heading.y * toShelf.x;
  if (Math.abs(cross) < 1e-6) return null;
  return cross > 0 ? "right" : "left";
}

export function buildInstructions(g: Graph, path: string[], shelf: Shelf, arrival: ArrivalInfo): RouteStep[] {
  const steps: RouteStep[] = [];
  const legs = toLegs(g, path);

  legs.forEach((leg, i) => {
    const target = g.nodes.get(leg.to)!.label;
    const dist = legDistance(g, leg.via);
    let text: string;
    if (i === 0) {
      const facing = g.nodes.get(leg.from)!.facingDeg;
      if (facing != null) {
        const turn = classifyTurn(signedAngle(headingFromFacing(facing), vec(g, leg.via[0], leg.via[1])));
        text =
          turn === "straight"
            ? `Walk straight ahead to ${target}, ${aboutMeters(dist)}.`
            : `${TURN_PHRASE[turn]}, then walk to ${target}, ${aboutMeters(dist)}.`;
      } else {
        text = `Head toward ${target}, ${aboutMeters(dist)}.`;
      }
    } else {
      const prev = legs[i - 1];
      const turn = classifyTurn(signedAngle(vec(g, prev.via.at(-2)!, prev.to), vec(g, leg.via[0], leg.via[1])));
      text = `${TURN_PHRASE[turn]} and continue to ${target}, ${aboutMeters(dist)}.`;
    }
    steps.push({ index: i, fromNodeId: leg.from, toNodeId: leg.to, distanceM: Math.round(dist * 10) / 10, text });
  });

  const anchor = path[path.length - 1];
  const side = shelfSide(g, path.length > 1 ? path[path.length - 2] : null, anchor, shelf);
  const where = [side ? `on your ${side}` : null, arrival.level ? `on the ${arrival.level} shelf` : null]
    .filter(Boolean)
    .join(", ");
  steps.push({
    index: steps.length,
    fromNodeId: anchor,
    toNodeId: anchor,
    distanceM: 0,
    text: `You have reached Aisle ${shelf.aisle}, section ${shelf.section}. ${arrival.productName} should be ${where || "at this section"}.`,
  });
  return steps;
}
